var warp1 = 20000; 	//金币传送
var warpItem = 5040000; 
var mapData = null;
function start() {
  status = -1;
  action(1, 0, 0);
}

function action(mode, type, selection) {
	if (mode < 1){
		im.dispose();
		return;
	}
    if (mode === 1) {
        status++;
    } else {
        status--;
    }

    if(!im.haveItem(id)){
		//强开
		im.dispose();
		return;
	}

	if (status === 0) {

		

		mapData = getMapId();
		
		var text = `\r\n\t#r${mapData.getStreetName()}#k 的 #r${mapData.getMapName()}#k\r\n\t有宝藏，赶快带上锄头去挖宝吧！`;
		
		text += "\r\n#b";
		//text += `#L1#花${formatUnit(warp1)}金币传送到地点（余额 ${formatUnit(im.getMeso())}）#l\r\n`;
		text += `#L2#使用 #t${warpItem}# 传送到地点#l\r\n`;

		im.sendSimple(text);
		
	

	} else if (status == 1){

		if(selection == 1){

			if(warp1 > im.getMeso()){
				im.sendOk("金币不足");
			}else{
				im.warp(mapData.getId());
				im.gainMeso(-warp1);
				im.getPlayer().saveLog(id,0,-warp1);
			}

		}else if(selection == 2){
			if(!im.getItemQuantity(warpItem)){
				im.sendOk("#t5040000#不足！");
			}else{
				im.warp(mapData.getId());
				im.gainItem(warpItem,-1);
				im.getPlayer().saveLog(id,warpItem,-1);
			}
		}
		
		im.dispose();
	} else {
		im.dispose();
	}
	
}




// 抽取一张地图，10次机会抽到一张限制未0的地图;
function getMapId(){


	var mapId = im.getPlayer().getData('藏宝图');

	if(mapId){
		return im.getClient().getChannelServer().getMapFactory().getMap(mapId * 1);
	}

	var back = null;
	for(let i=0;i < 10;i++){
		const randomIndex = Math.floor(Math.random() * map.length);
		mapId = map[randomIndex];
		var mapData = im.getClient().getChannelServer().getMapFactory().getMap(mapId);
		//确保抽取到的地图是一张无限制的普通地图
		if(mapData.getFieldLimit() == 0){
			back = mapData;
			im.getPlayer().saveData('藏宝图',mapId);
			break;
		}
	}

	// im.message("名字：" + mapData.getMapName());
	// im.message("补充：" + mapData.getStreetName());
	// im.message("是否允许召唤：" + mapData.getSummonState());
	// im.message("主城：" + mapData.isTown());
	// im.message("限制：" + mapData.getFieldLimit());
	return back;
	
}



/**
 * 格式化数字，超过万/亿时显示对应单位
 * @param {number|string} num - 要格式化的数字（支持数字或数字字符串）
 * @param {number} decimalDigits - 保留的小数位数，默认2位
 * @returns {string} 格式化后的字符串
 */
function formatUnit(num, decimalDigits = 2) {
    // 1. 转换为数字并校验合法性
    const number = Number(num);
    if (isNaN(number)) {
        return '0'; // 非数字返回0
    }

    // 定义单位对应的阈值和除数
    const units = [
        { threshold: 1e8, divisor: 1e8, unit: '亿' }, // 1亿 = 100000000
        { threshold: 1e4, divisor: 1e4, unit: '万' }, // 1万 = 10000
    ];

    // 2. 遍历单位，判断数字所属区间
    for (const item of units) {
        if (Math.abs(number) >= item.threshold) {
            // 计算转换后的值并保留指定小数位
            const converted = (number / item.divisor).toFixed(decimalDigits) * 1;
            // 去除末尾的0和多余的小数点（例如1.00万 → 1万，1.20亿 → 1.2亿）
            const formatted = parseFloat(converted).toString();
            return formatted + item.unit;
        }
    }

    // 3. 小于万的数字，直接返回（也可根据需求保留小数位）
    return number.toFixed(decimalDigits) * 1;
}